public class Main {
    static int calculateMinimumHP(int[][] dungeon) {
        int m = dungeon.length, n = dungeon[0].length;
        int[][] dp = new int[m + 1][n + 1];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);
        dp[m][n - 1] = 1;                                          // virtual: just past the destination
        dp[m - 1][n] = 1;
        for (int i = m - 1; i >= 0; i--) {                          // fill BACKWARD from the destination
            for (int j = n - 1; j >= 0; j--) {
                int need = Math.min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j];
                dp[i][j] = Math.max(1, need);                          // health can never drop below 1
            }
        }
        return dp[0][0];
    }
}

